def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # If it's already a mapping, return it unchanged
    if isinstance(value, dict):
        return value

    # If it's a tuple or list, convert to a list for JSON serializability
    if isinstance(value, (tuple, list)):
        return list(value)

    # If it's a namedtuple or has an _asdict method (e.g., collections.namedtuple)
    if hasattr(value, "_asdict"):
        try:
            return value._asdict()
        except Exception:
            pass

    # If it has a __dict__ attribute (most custom objects)
    if hasattr(value, "__dict__"):
        return value.__dict__

    # Try to extract common coordinate attributes
    attrs = {}
    for attr in ("x", "y", "z"):
        if hasattr(value, attr):
            attrs[attr] = getattr(value, attr)
    if attrs:
        return attrs

    # Fallback: return the value itself (may not be serializable)
    return value

