def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying mapping of the record
    data = None
    if hasattr(self, "_data") and isinstance(getattr(self, "_data"), dict):
        data = getattr(self, "_data")
    elif hasattr(self, "data") and isinstance(getattr(self, "data"), dict):
        data = getattr(self, "data")
    elif hasattr(self, "items") and callable(getattr(self, "items")):
        try:
            data = dict(self.items())
        except Exception:
            data = None
    if data is None:
        # Fallback: use public attributes of the instance
        data = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}

    # If no keys specified, return all values
    if not keys:
        return list(data.values())

    # Prepare list of values based on provided keys
    result = []
    values_list = list(data.values())
    for key in keys:
        if isinstance(key, int):
            # Treat as index
            try:
                result.append(values_list[key])
            except IndexError:
                raise KeyError(f"Index {key} out of range")
        else:
            # Treat as key
            if key in data:
                result.append(data[key])
            else:
                raise KeyError(f"Key {key!r} not found")
    return result

