def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        # Skip if cls is already a subclass of any class in result
        if not any(issubclass(cls, base) for base in result):
            result.append(cls)
    return result

