def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to a list of values
    try:
        coord_vals = list(coord)
    except TypeError:
        coord_vals = [coord]

    ndim = len(self._edges)
    if len(coord_vals) != ndim:
        raise ValueError("Coordinate dimensionality does not match histogram.")

    bin_indices = []
    for dim, val in enumerate(coord_vals):
        edges = self._edges[dim]
        # Check if value is within the overall range
        if val < edges[0] or val >= edges[-1]:
            return  # outside histogram bounds, ignore
        # Find the bin index for this dimension
        bin_idx = None
        for i in range(len(edges) - 1):
            if edges[i] <= val < edges[i + 1]:
                bin_idx = i
                break
        if bin_idx is None:
            return  # value falls outside the bin edges, ignore
        bin_indices.append(bin_idx)

    # Increment the histogram count at the found bin
    try:
        # Works for numpy arrays
        self._counts[tuple(bin_indices)] += weight
    except Exception:
        # Fallback for nested list structures
        c = self._counts
        for i in bin_indices[:-1]:
            c = c[i]
        c[bin_indices[-1]] += weight

