def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Helper functions to validate label key/value according to Kubernetes rules.
    # Keys and values must start and end with an alphanumeric character and may contain
    # alphanumerics, '-', '_' or '.' in between.
    def _is_valid_label_key(key: str) -> bool:
        if not key:
            return False
        allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.")
        if key[0] not in allowed or key[-1] not in allowed:
            return False
        for c in key:
            if c not in allowed:
                return False
        return True

    def _is_valid_label_value(value: str) -> bool:
        if not value:
            return False
        allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.")
        if value[0] not in allowed or value[-1] not in allowed:
            return False
        for c in value:
            if c not in allowed:
                return False
        return True

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not _is_valid_label_key(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex [...]"})

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): "expected string or bytes-like object"})
                else:
                    v_str = v.decode() if isinstance(v, bytes) else v
                    if not _is_valid_label_value(v_str):
                        errors.append({v_str: f"Label value '{v_str}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): "expected string or bytes-like object"})
            else:
                v_str = value.decode() if isinstance(value, bytes) else value
                if not _is_valid_label_value(v_str):
                    errors.append({v_str: f"Label value '{v_str}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

