def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    # Resolve the root directory from a string path or a pyfs root object
    if isinstance(path, str):
        root = path
    else:
        # Assume a pyfs root object exposes a 'path' attribute
        root = getattr(path, "path", None)
        if root is None:
            return False
    # Must be an existing directory
    if not os.path.isdir(root):
        return False
    # Must contain a .ocfl_version file
    ocfl_version_file = os.path.join(root, ".ocfl_version")
    if not os.path.isfile(ocfl_version_file):
        return False
    # The .ocfl_version file should contain a numeric version string
    try:
        with open(ocfl_version_file, "r") as f:
            content = f.read().strip()
        if not content.isdigit():
            return False
    except Exception:
        return False
    # Basic validation passed
    return True

