def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure inventory is a mapping from version to logical_path -> set(content_files)
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping versions to logical path maps")

    # Base mapping for the requested version
    base_map = inventory.get(version, {})
    if not isinstance(base_map, dict):
        raise TypeError(f"inventory[{version!r}] must be a dict mapping logical paths to sets of files")

    # Start with a copy of the base mapping
    result = {lp: set(files) for lp, files in base_map.items()}

    # Include duplicates from later versions
    for later_version in sorted(inventory.keys()):
        if later_version <= version:
            continue
        later_map = inventory.get(later_version, {})
        if not isinstance(later_map, dict):
            continue  # skip malformed entries
        for lp, files in later_map.items():
            if not isinstance(files, (set, list, tuple)):
                continue  # skip malformed file lists
            if lp in result:
                result[lp].update(files)
            else:
                result[lp] = set(files)

    return result

