def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    os = __import__('os')
    data = {}
    # List all files in the folder
    try:
        files = os.listdir(folder)
    except Exception:
        return {}
    # Find all XML files and their basenames
    xml_basenames = set()
    for f in files:
        if f.lower().endswith('.xml'):
            basename = os.path.splitext(f)[0]
            xml_basenames.add(basename)
    # For each basename, collect all files that share the same basename
    for basename in xml_basenames:
        group = []
        for f in files:
            name, ext = os.path.splitext(f)
            if name == basename:
                full_path = os.path.join(folder, f)
                if os.path.isfile(full_path):
                    group.append(full_path)
        if group:
            data[basename] = group
    return data

