def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _pretty(obj, level):
        space = ' ' * (level * 4)
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                items.append(f"{space}{repr(k)}: {_pretty(v, level + 1)}")
            return "{\n" + ",\n".join(items) + f"\n{space}}}"
        elif isinstance(obj, (list, tuple, set)):
            cls_name = type(obj).__name__
            items = []
            for v in obj:
                items.append(f"{space}{_pretty(v, level + 1)}")
            sep = ",\n"
            if isinstance(obj, list):
                return f"{cls_name}([\n" + sep.join(items) + f"\n{space}])"
            elif isinstance(obj, tuple):
                return f"{cls_name}(\n" + sep.join(items) + f"\n{space})"
            else:  # set
                return f"{cls_name}(\n" + sep.join(items) + f"\n{space})"
        elif hasattr(obj, "__dict__"):
            cls_name = type(obj).__name__
            items = []
            for k, v in obj.__dict__.items():
                items.append(f"{space}{k}={_pretty(v, level + 1)}")
            return f"{cls_name}(\n" + ",\n".join(items) + f"\n{space})"
        else:
            if debug:
                return f"{repr(obj)} ({type(obj).__name__})"
            return repr(obj)

    return _pretty(self, indent)

