        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Determine the collection of objects to validate.
        # Prefer a dedicated attribute; fall back to an empty list if not present.
        objects = getattr(self, 'objects', [])
        if not isinstance(objects, (list, tuple)):
            # If objects is a single item, wrap it in a list.
            objects = [objects]

        for obj in objects:
            num_objects += 1
            is_valid = True

            if validate_objects:
                try:
                    if hasattr(obj, 'validate'):
                        result = obj.validate()
                        if not result:
                            is_valid = False
                            if show_warnings:
                                print(f"Validation failed for object: {obj}")
                    else:
                        is_valid = False
                        if show_warnings:
                            print(f"No validate method for object: {obj}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Exception during validation of {obj}: {exc}")

            if check_digests:
                try:
                    if hasattr(obj, 'check_digest'):
                        result = obj.check_digest()
                        if not result:
                            is_valid = False
                            if show_warnings:
                                print(f"Digest check failed for object: {obj}")
                    else:
                        is_valid = False
                        if show_warnings:
                            print(f"No check_digest method for object: {obj}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Exception during digest check of {obj}: {exc}")

            if is_valid:
