def deep_merge_nodes(nodes):
    """
    Merge a list of (key_node, value_node) tuples, deep merging mapping values for duplicate keys.
    """
    from collections import OrderedDict

    def merge_values(v1, v2):
        # Helper to merge two values, deep merging if both are MappingNodes
        if type(v1).__name__ == 'MappingNode' and type(v2).__name__ == 'MappingNode':
            # Merge the mapping node values recursively
            merged_list = deep_merge_nodes(v1.value + v2.value)
            # Preserve the tag of the first mapping node
            return type(v1)(tag=v1.tag, value=merged_list)
        # For non-mapping values, the second value wins
        return v2

    merged = OrderedDict()
    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_val_node = merged[key]
            merged_val = merge_values(existing_val_node, val_node)
            merged[key] = (existing_key_node, merged_val)
        else:
