def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import the exception class from zope.interface
    try:
        from zope.interface import Invalid
    except Exception:
        # Fallback: define a minimal Invalid exception if zope.interface is not available
        class Invalid(Exception):
            pass

    errors = []

    # Check that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy for {candidate!r}: {exc}")

    # Iterate over all names defined by the interface
    for name in iface.names():
        # Skip private names that are not part of the public API
        if name.startswith('_'):
            continue

        # Check that the candidate has the attribute
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} missing attribute {name!r}")
            continue

        attr = getattr(candidate, name)

        # Determine whether the interface expects a method or an attribute
        method = iface.getMethod(name)
        attribute = iface.getAttribute(name)

        if method:
            # The interface expects a method
            if not callable(attr):
                errors.append(f"{candidate!r} attribute {name!r} is not callable")
            else:
                # Optional: check signature compatibility
                try:
                    import inspect
                    iface_sig = method.signature
                    cand_sig = inspect.signature(attr)
                    # Compare the number of parameters and their kinds
                    if len(iface_sig.parameters) != len(cand_sig.parameters):
                        errors.append(
                            f"{candidate!r} method {name!r} signature mismatch: "
                            f"expected {len(iface_sig.parameters)} params, got {len(cand_sig.parameters)}"
                        )
                    else:
                        for p_name, p in iface_sig.parameters.items():
                            if p_name not in cand_sig.parameters:
                                errors.append(
                                    f"{candidate!r} method {name!r} missing parameter {p_name!r}"
                                )
                except Exception:
                    # If signature inspection fails, ignore it
                    pass
        elif attribute:
            # The interface expects an attribute (not callable)
            if callable(attr):
                errors.append(f"{candidate!r} attribute {name!r} should not be callable")

    # Raise collected errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

