    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate satisfies the interface, False otherwise.
    """
    if candidate is None:
        return False

    # Helper to get the object to inspect (class or instance)
    def _obj(o):
        return o if isinstance(o, type) else o

    # If iface is a class (or tuple of classes), try subclass/instance checks first
    if isinstance(iface, type) or (isinstance(iface, tuple) and all(isinstance(i, type) for i in iface)):
        # If candidate is a class
        if isinstance(candidate, type):
            try:
                if isinstance(iface, tuple):
                    if issubclass(candidate, iface):
                        return True
                else:
                    if issubclass(candidate, iface):
                        return True
            except TypeError:
                pass
        # If candidate is an instance
        if isinstance(candidate, iface):
            return True

