    # Get the attributes that define the interface
    if isinstance(iface, type):
        iface_attrs = [attr for attr in dir(iface) if not attr.startswith('__')]
    else:
        # If iface is not a class, we cannot introspect; assume failure
        return False

    # Determine the object to inspect (class or instance)
    inspect_obj = _obj(candidate)

    for attr in iface_attrs:
        if not hasattr(inspect_obj, attr):
            if tentative:
                continue
            return False
        iface_val = getattr(iface, attr)
        cand_val = getattr(inspect_obj, attr)
        # If the interface attribute is callable, ensure candidate's is callable
        if callable(iface_val):
            if not callable(cand_val):
                return False
        else:
            # For non-callable attributes, we don't enforce type equality
