def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache is not empty
    if not hasattr(self, "key_to_val") or not self.key_to_val:
        raise KeyError("popitem(): dictionary is empty")

    # Find the minimum frequency among all keys
    min_freq = min(self.key_to_freq.values())

    # Locate a key that has this minimum frequency
    for key, freq in self.key_to_freq.items():
        if freq == min_freq:
            break

    # Retrieve the value and remove the key from all structures
    value = self.key_to_val.pop(key)
    self.key_to_freq.pop(key)

    # If the cache maintains a mapping from frequency to keys, update it
    if hasattr(self, "freq_to_keys"):
        freq_dict = self.freq_to_keys.get(min_freq)
        if freq_dict is not None:
            freq_dict.pop(key, None)
            if not freq_dict:
                del self.freq_to_keys[min_freq]
                # Update the minimum frequency if necessary
                if self.freq_to_keys:
                    self.min_freq = min(self.freq_to_keys)

    return key, value

