def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import base64
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception:
        # Required libraries are not available
        return False

    # Load the public key (PEM format expected)
    try:
        if isinstance(public_key, str):
            key_bytes = public_key.encode()
        else:
            key_bytes = public_key
        pub_key = serialization.load_pem_public_key(key_bytes)
    except Exception:
        return False

    # Compute the hash of the document
    try:
        if isinstance(doc, str):
            doc_bytes = doc.encode()
        else:
            doc_bytes = doc
        digest = hashes.Hash(hashes.SHA256())
        digest.update(doc_bytes)
        doc_hash = digest.finalize()
    except Exception:
        return False

    # Decode the provided signature (base64 encoded)
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Verify the signature
    try:
        pub_key.verify(
            sig_bytes,
            doc_hash,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

