def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def merge_dict(target, source):
        for key, value in source.items():
            if key in target:
                if isinstance(target[key], list) and isinstance(value, list):
                    target[key].extend(value)
                else:
                    target[key] = value
            else:
                target[key] = value

    def resolve_section(section):
        if not isinstance(section, dict):
            return
        includes = section.pop('include', None)
        if includes:
            if not isinstance(includes, list):
                includes = [includes]
            for inc in includes:
                inc_path = os.path.join(self.base_path, inc)
                inc_path = os.path.abspath(inc_path)
                if inc_path in visited:
                    continue
                visited.add(inc_path)
                inc_dict = self._parse_file(inc_path)
                resolve_section(inc_dict)
                merge_dict(section, inc_dict)
        for value in list(section.values()):
            if isinstance(value, dict):
                resolve_section(value)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        resolve_section(item)

    resolve_section(parser_dict)
    return parser_dict

