def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Ensure the command exists
    if command_name not in self.commands:
        raise KeyError(f"Command '{command_name}' not found")

    command = self.commands[command_name]

    # If the command is a dictionary, look up directly
    if isinstance(command, dict):
        if argument_name not in command:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")
        return command[argument_name]

    # If the command has an 'options' attribute, use it
    if hasattr(command, "options"):
        options = command.options
        if argument_name not in options:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")
        return options[argument_name]

    # Fallback: try treating the command as a mapping
    try:
        return command[argument_name]
    except Exception as exc:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'") from exc

