def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected to be a dictionary where each key maps to a tuple
                 of the form (value, max_length). If the value is None or not a string/list/tuple,
                 it is ignored. If the length of the value exceeds max_length, a ValueError is raised.
    """
    for name, spec in args.items():
        # Expect spec to be a tuple (value, max_length)
        if not isinstance(spec, (tuple, list)) or len(spec) != 2:
            raise TypeError(f"Argument '{name}' must be a tuple/list of (value, max_length)")
        value, max_length = spec
        # Skip None values
        if value is None:
            continue
        # Only check for string, list, tuple, set, dict types
        if isinstance(value, (str, list, tuple, set, dict)):
            if len(value) > max_length:
                raise ValueError(f"Argument '{name}' length {len(value)} exceeds maximum allowed {max_length}")
        else:
            # For other types, we cannot determine length; skip or raise
            continue
    return True

