    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure that the instance has min and max attributes
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("Instance must have 'min' and 'max' attributes defined.")
    min_val = self.min
    max_val = self.max

    # If args is a mapping, validate each key/value pair
    if isinstance(args, dict):
        for key, value in args.items():
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument '{key}' with value {value} is out of bounds "
                    f"[{min_val}, {max_val}]"
                )
    # If args is an iterable (but not a string/bytes), validate each element
    elif hasattr(args, "__iter__") and not isinstance(args, (str, bytes)):
        for idx, value in enumerate(args):
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument at position {idx} with value {value} is out of bounds "
                    f"[{min_val}, {max_val}]"
                )
    else:
        # If args is a single value, validate it directly
        if not (min_val <= args <= max_val):
            raise ValueError(
                f"Argument value {args} is out of bounds [{min_val}, {max_val}]"
            )
    # If all checks pass, simply return None (or you could return True)
    return None

