def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare containers
    control_args = {}
    nested_args = {}

    # Convert args to a dictionary if necessary
    if isinstance(args, dict):
        arg_dict = args
    elif isinstance(args, list):
        # If list of tuples, convert directly
        if all(isinstance(item, tuple) and len(item) == 2 for item in args):
            arg_dict = dict(args)
        else:
            # Assume alternating key/value pairs
            arg_dict = {}
            it = iter(args)
            for key in it:
                try:
                    value = next(it)
                except StopIteration:
                    break
                arg_dict[key] = value
    else:
        # Unsupported type; return empty dicts
        return {}, {}

    # Define prefixes that identify control arguments
    control_prefixes = ("control_", "--control-")

    for key, value in arg_dict.items():
        # Normalize key for prefix checking
        norm_key = key.lstrip("-")
        if norm_key.startswith("control_") or key.startswith("--control-"):
            control_args[key] = value
        else:
            # All other arguments (including custom) are treated as nested
            nested_args[key] = value

    return control_args, nested_args

