def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    # Allow a single string to be passed
    if isinstance(extra_vars, str):
        extra_vars = [extra_vars]
    # If a dict is passed, just update
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    for var in extra_vars:
        if "=" in var:
            key, val = var.split("=", 1)
            key = key.strip()
            val = val.strip()
            # Basic type conversion
            low = val.lower()
            if low == "true":
                val = True
            elif low == "false":
                val = False
            elif low == "null":
                val = None
            else:
                # Try numeric conversion
                try:
                    val = int(val)
                except ValueError:
                    try:
                        val = float(val)
                    except ValueError:
                        pass
            vars_dict[key] = val
        else:
            # No value provided, set to True
            vars_dict[var.strip()] = True
    return vars_dict

